// Unit test — @MockitoBean on ChatModel
@SpringBootTest
class TicketClassifierTest {

    @MockitoBean
    ChatModel chatModel;

    @Autowired
    TicketClassifierService classifier;

    @Test
    void classifiesBugTicket() {
        // Arrange — fixed response fixture
        ChatResponse fixedResponse = new ChatResponse(
            List.of(new Generation(new AssistantMessage("BUG")))
        );
        when(chatModel.call(any(Prompt.class))).thenReturn(fixedResponse);

        // Act
        String category = classifier.classify("NPE on startup after upgrade");

        // Assert
        assertThat(category).isEqualTo("BUG");
    }
}

// InMemoryChatModel — scripted responses without Mockito
@Test
void usesPromptTemplateVariables() {
    // InMemoryChatModel returns responses in round-robin order
    ChatModel stub = new InMemoryChatModel(
        new ChatResponse(List.of(new Generation(new AssistantMessage("FEATURE"))))
    );
    TicketClassifierService svc = new TicketClassifierService(stub);
    assertThat(svc.classify("Add dark mode")).isEqualTo("FEATURE");
}
