// Pattern 1: InMemoryChatModel — no Mockito needed
@Test
void classifiesTicketAsBug() {
    // Script a fixed response
    ChatResponse stubResponse = new ChatResponse(
        List.of(new Generation(new AssistantMessage("BUG")))
    );
    InMemoryChatModel stub = new InMemoryChatModel(stubResponse);
    TicketClassifierService svc = new TicketClassifierService(stub);

    String result = svc.classify("NPE on startup");
    assertThat(result).isEqualTo("BUG");
}

// Pattern 2: @MockitoBean in @SpringBootTest — full context with mock model
@SpringBootTest
class TicketClassifierIntegrationTest {

    @MockitoBean
    ChatModel chatModel;

    @Autowired
    TicketClassifierService classifier;

    @Test
    void usesPromptTemplateCorrectly() {
        ChatResponse fixedResponse = new ChatResponse(
            List.of(new Generation(new AssistantMessage("FEATURE")))
        );
        when(chatModel.call(any(Prompt.class))).thenReturn(fixedResponse);

        String result = classifier.classify("Add dark mode support");
        assertThat(result).isEqualTo("FEATURE");

        // Also verify the prompt was constructed correctly
        ArgumentCaptor<Prompt> captor = ArgumentCaptor.forClass(Prompt.class);
        verify(chatModel).call(captor.capture());
        String promptText = captor.getValue().getContents();
        assertThat(promptText).contains("Add dark mode support");
    }
}
