@SpringBootTest
class TicketAnswerEvalTest {

    @Autowired
    ChatModel chatModel;     // real model or high-quality mock for eval

    @Test
    void answerIsRelevantToQuestion() {
        RelevancyEvaluator evaluator = new RelevancyEvaluator(chatModel);

        // Build evaluation input
        EvaluationRequest request = new EvaluationRequest(
            "What causes a NullPointerException in Java?",    // original question
            List.of(new Document("NPE occurs when...")),       // retrieved context
            "A NullPointerException is thrown when..."         // LLM's answer
        );

        EvaluationResponse result = evaluator.evaluate(request);

        // RelevancyEvaluator returns true if the answer is relevant to the question
        assertThat(result.isPass()).isTrue();
    }
}

// Lightweight format check — no judge model needed
@Test
void answerIsValidJson() {
    InMemoryChatModel stub = new InMemoryChatModel(
        new ChatResponse(List.of(new Generation(
            new AssistantMessage("{\"category\": \"BUG\", \"confidence\": 0.92}")
        )))
    );
    TicketClassifierService svc = new TicketClassifierService(stub);
    String json = svc.classifyAsJson("NPE on startup");
    // Assert JSON structure without a judge model
    assertThatJson(json).node("category").isEqualTo("BUG");
    assertThatJson(json).node("confidence").isNumber();
}
